package org.rsmod.content.other.treasuretrails.pack

import dev.openrune.definition.dbtables.dbTable
import dev.openrune.definition.util.VarType

/**
 * Easy to elite clue scroll objs and their `cluehelper_clue_*` step rows. Generated by joining the
 * RuneLite clue scroll plugin (runelite/runelite@e336ac2, BSD-2-Clause) against the rev 240
 * cache.
 *
 * A step holds more than one row only where the target depends on player state (Nieve/Steve).
 */
object TrailClueObjTable {
    const val OBJ = 0
    const val STEP = 1

    fun clueObjs() =
        dbTable("dbtable.trail_clue_obj", serverOnly = true) {
            column("obj", OBJ, VarType.OBJ)
            column("step", STEP, VarType.DBROW)

            fun clue(row: String, obj: String, vararg steps: String) {
                row(row) {
                    columnRSCM(OBJ, obj)
                    columnRSCM(STEP, *steps)
                }
            }

            clue(
                "dbrow.trail_clue_easy_simple001_step",
                "obj.trail_clue_easy_simple001",
                "dbrow.cluehelper_cryptic_easy_chestclosed",
